            "content": "export { ProButton, type ProButtonCopyOptions, type ProButtonProps } from './button'\nexport { type ProCopyOptions, type ProCopyStatus, useProCopy } from './copy'\nexport {\n  type ProFullscreenMode,\n  type UseProFullscreenOptions,\n  useProFullscreen,\n} from './fullscreen'\n",
