            "target": "pro-base/copy.ts",
            "content": "'use client'\n\nimport * as React from 'react'\n\nexport type ProCopyStatus = 'idle' | 'copying' | 'success' | 'error'\n\nexport interface ProCopyOptions {\n  text: string | (() => string | Promise<string>)\n  resetDuration?: number\n  onSuccess?: (text: string) => void | Promise<void>\n  onError?: (error: unknown) => void | Promise<void>\n}\n\nexport function useProCopy(options?: ProCopyOptions) {\n  const [status, setStatus] = React.useState<ProCopyStatus>('idle')\n\n  React.useEffect(() => {\n    const resetDuration = options?.resetDuration ?? 2000\n    if ((status !== 'success' && status !== 'error') || resetDuration <= 0) return\n    const timer = window.setTimeout(() => setStatus('idle'), resetDuration)\n    return () => window.clearTimeout(timer)\n  }, [status, options?.resetDuration])\n\n  const copy = React.useCallback(async () => {\n    if (!options || status === 'copying') return\n\n    setStatus('copying')\n    try {\n      const text = typeof options.text === 'function' ? await options.text() : options.text\n      await copyToClipboard(text)\n      setStatus('success')\n      await options.onSuccess?.(text)\n    } catch (error) {\n      setStatus('error')\n      await options.onError?.(error)\n    }\n  }, [options, status])\n\n  const reset = React.useCallback(() => setStatus('idle'), [])\n\n  return {\n    copy,\n    reset,\n    status,\n    copying: status === 'copying',\n    copied: status === 'success',\n    failed: status === 'error',\n  }\n}\n\nasync function copyToClipboard(text: string) {\n  if (navigator.clipboard?.writeText) {\n    await navigator.clipboard.writeText(text)\n    return\n  }\n\n  const textarea = document.createElement('textarea')\n  textarea.value = text\n  textarea.setAttribute('readonly', '')\n  textarea.style.position = 'fixed'\n  textarea.style.top = '-9999px'\n  textarea.style.opacity = '0'\n  document.body.appendChild(textarea)\n  textarea.select()\n\n  try {\n    const copied = document.execCommand('copy')\n    if (!copied) throw new Error('Copy command was rejected.')\n  } finally {\n    document.body.removeChild(textarea)\n  }\n}\n",
