            "target": "pro-form/form-item.tsx",
            "content": "'use client'\n\nimport { useField } from '@formily/react'\nimport { observer } from '@formily/reactive-react'\nimport { InfoIcon } from 'lucide-react'\nimport type { ReactNode } from 'react'\nimport { Label } from '@/components/ui/label'\nimport { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip'\nimport { cn } from '@/lib/utils'\n\nexport interface FormItemProps {\n  className?: string\n  children?: ReactNode\n  /**\n   * Override label (falls back to field.title)\n   */\n  label?: string\n  /**\n   * Override required (falls back to field.required)\n   */\n  required?: boolean\n  /**\n   * Field description. Falls back to field.description and renders as the label tooltip.\n   */\n  description?: ReactNode\n  /**\n   * Optional label tooltip\n   */\n  tooltip?: ReactNode\n  extra?: ReactNode\n}\n\nexport const FormItem = observer(\n  ({ className, children, label, required, description, tooltip, extra }: FormItemProps) => {\n    const field = useField()\n    const formField = field as {\n      title?: string\n      required?: boolean\n      selfErrors?: string[]\n      description?: ReactNode\n      path?: { toString: () => string }\n      disabled?: boolean\n    }\n\n    const fieldLabel = label ?? formField.title\n    const fieldRequired = required ?? formField.required\n    const errors = formField.selfErrors ?? []\n    const fieldTooltip = tooltip ?? description ?? formField.description\n    const fieldExtra = extra\n\n    return (\n      <div className={cn('space-y-1.5', className)}>\n        {fieldLabel && (\n          <div className=\"flex items-center gap-1.5\">\n            <Label\n              htmlFor={formField.path?.toString()}\n              className={cn(\n                'text-sm font-medium leading-none',\n                formField.disabled && 'cursor-not-allowed opacity-50',\n              )}\n            >\n              {fieldLabel}\n            </Label>\n            {fieldTooltip && (\n              <TooltipProvider>\n                <Tooltip>\n                  <TooltipTrigger asChild>\n                    <InfoIcon className=\"size-3.5 cursor-help text-muted-foreground\" />\n                  </TooltipTrigger>\n                  <TooltipContent side=\"right\">\n                    <p className=\"max-w-xs text-xs\">{fieldTooltip}</p>\n                  </TooltipContent>\n                </Tooltip>\n              </TooltipProvider>\n            )}\n            {fieldRequired && (\n              <span className=\"text-destructive\" aria-hidden=\"true\">\n                *\n              </span>\n            )}\n          </div>\n        )}\n\n        {children}\n\n        {errors.length > 0 && (\n          <p className=\"text-xs text-destructive\" role=\"alert\">\n            {errors.join(', ')}\n          </p>\n        )}\n\n        {fieldExtra && <div className=\"text-xs text-muted-foreground\">{fieldExtra}</div>}\n      </div>\n    )\n  },\n)\n\nFormItem.displayName = 'FormItem'\n",
