            "target": "pro-fields/radio.tsx",
            "content": "'use client'\n\nimport * as React from 'react'\nimport { Label } from '@/components/ui/label'\nimport { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'\nimport { cn } from '@/lib/utils'\n\nexport interface RadioOption {\n  label: React.ReactNode\n  value: string\n  description?: React.ReactNode\n  disabled?: boolean\n}\n\nexport interface RadioProps\n  extends Omit<\n    React.ComponentProps<typeof RadioGroup>,\n    'value' | 'defaultValue' | 'onChange' | 'onValueChange' | 'disabled'\n  > {\n  value?: string\n  defaultValue?: string\n  onChange?: (value: string) => void\n  disabled?: boolean\n  options?: RadioOption[]\n  itemClassName?: string\n  labelClassName?: string\n}\n\nexport function Radio({\n  value,\n  defaultValue,\n  onChange,\n  disabled,\n  options = [],\n  className,\n  itemClassName,\n  labelClassName,\n  ...props\n}: RadioProps) {\n  const generatedId = React.useId()\n\n  return (\n    <RadioGroup\n      value={value}\n      defaultValue={defaultValue}\n      onValueChange={(nextValue) => onChange?.(nextValue)}\n      disabled={disabled}\n      className={cn('flex flex-col gap-2', className)}\n      {...props}\n    >\n      {options.map((opt, index) => {\n        const itemId = `${generatedId}-${index}`\n\n        return (\n          <div key={opt.value} className={cn('flex items-start gap-2', itemClassName)}>\n            <RadioGroupItem value={opt.value} id={itemId} disabled={opt.disabled} />\n            <Label\n              htmlFor={itemId}\n              className={cn('grid cursor-pointer gap-1 font-normal leading-none', labelClassName)}\n            >\n              <span>{opt.label}</span>\n              {opt.description && (\n                <span className=\"text-xs leading-snug text-muted-foreground\">\n                  {opt.description}\n                </span>\n              )}\n            </Label>\n          </div>\n        )\n      })}\n    </RadioGroup>\n  )\n}\n",
