            "target": "pro-fields/date-picker.tsx",
            "content": "'use client'\n\nimport { format } from 'date-fns'\nimport { CalendarIcon, X } from 'lucide-react'\nimport type * as React from 'react'\nimport { Button } from '@/components/ui/button'\nimport { Calendar } from '@/components/ui/calendar'\nimport { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'\nimport { cn } from '@/lib/utils'\n\nexport interface DatePickerBaseProps {\n  value?: Date\n  onChange?: (date: Date | undefined) => void\n  disabled?: boolean\n  placeholder?: string\n  dateFormat?: string\n  allowClear?: boolean\n  className?: string\n}\n\nexport function DatePicker({\n  value,\n  onChange,\n  disabled,\n  placeholder = 'Pick a date',\n  dateFormat = 'PPP',\n  allowClear,\n  className,\n}: DatePickerBaseProps) {\n  const showClear = allowClear && value && !disabled\n\n  function handleClear(\n    event: React.PointerEvent<HTMLButtonElement> | React.MouseEvent<HTMLButtonElement>,\n  ) {\n    event.preventDefault()\n    event.stopPropagation()\n    onChange?.(undefined)\n  }\n\n  return (\n    <Popover>\n      <div className={cn('relative w-full', className)}>\n        <PopoverTrigger asChild>\n          <Button\n            variant=\"outline\"\n            disabled={disabled}\n            className={cn(\n              'w-full justify-start text-left font-normal',\n              showClear && 'pr-8',\n              !value && 'text-muted-foreground',\n            )}\n          >\n            <CalendarIcon className=\"mr-2 size-4\" />\n            <span className=\"min-w-0 flex-1 truncate text-left\">\n              {value ? format(value, dateFormat) : placeholder}\n            </span>\n          </Button>\n        </PopoverTrigger>\n        {showClear && (\n          <button\n            type=\"button\"\n            tabIndex={-1}\n            aria-label=\"Clear date\"\n            onPointerDown={handleClear}\n            onClick={handleClear}\n            className=\"absolute top-1/2 right-2 z-10 flex size-5 -translate-y-1/2 items-center justify-center text-muted-foreground transition-colors hover:text-foreground\"\n          >\n            <X size={14} />\n          </button>\n        )}\n      </div>\n      <PopoverContent className=\"w-auto p-0\" align=\"start\">\n        <Calendar mode=\"single\" selected={value} onSelect={onChange} />\n      </PopoverContent>\n    </Popover>\n  )\n}\n",
