            "target": "pro-fields/tree-select.tsx",
            "content": "'use client'\n\nimport { Check, ChevronDown, ChevronRight, X } from 'lucide-react'\nimport * as React from 'react'\nimport { Button } from '@/components/ui/button'\nimport { Checkbox } from '@/components/ui/checkbox'\nimport { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'\nimport { cn } from '@/lib/utils'\n\nexport interface TreeSelectOption {\n  label: string\n  value: string\n  disabled?: boolean\n  children?: TreeSelectOption[]\n}\n\nexport interface TreeSelectProps {\n  value?: string[]\n  onChange?: (value: string[]) => void\n  options?: TreeSelectOption[]\n  placeholder?: string\n  disabled?: boolean\n  required?: boolean\n  allowClear?: boolean\n  multiple?: boolean\n  className?: string\n}\n\nfunction getLabels(options: TreeSelectOption[], values: string[]): string {\n  const labels: string[] = []\n  function traverse(opts: TreeSelectOption[]) {\n    for (const opt of opts) {\n      if (values.includes(opt.value)) labels.push(opt.label)\n      if (opt.children) traverse(opt.children)\n    }\n  }\n  traverse(options)\n  return labels.join(', ')\n}\n\nfunction TreeNode({\n  option,\n  selected,\n  onToggle,\n  multiple,\n}: {\n  option: TreeSelectOption\n  selected: string[]\n  onToggle: (value: string) => void\n  multiple?: boolean\n}) {\n  const [expanded, setExpanded] = React.useState(false)\n  const hasChildren = Boolean(option.children?.length)\n  const isSelected = selected.includes(option.value)\n\n  return (\n    <li>\n      <div\n        className={cn(\n          'flex items-center gap-1.5 rounded-sm px-2 py-1 text-sm',\n          option.disabled && 'cursor-not-allowed opacity-50',\n        )}\n      >\n        <button\n          type=\"button\"\n          aria-label={expanded ? 'Collapse' : 'Expand'}\n          className=\"flex size-4 shrink-0 items-center justify-center\"\n          onClick={() => hasChildren && setExpanded(!expanded)}\n        >\n          {hasChildren ? (\n            expanded ? (\n              <ChevronDown className=\"size-3\" />\n            ) : (\n              <ChevronRight className=\"size-3\" />\n            )\n          ) : null}\n        </button>\n        {multiple ? (\n          <>\n            <Checkbox\n              checked={isSelected}\n              disabled={option.disabled}\n              onCheckedChange={() => !option.disabled && onToggle(option.value)}\n              aria-label={option.label}\n            />\n            <button\n              type=\"button\"\n              disabled={option.disabled}\n              onClick={() => !option.disabled && onToggle(option.value)}\n              onKeyDown={(e) => e.key === 'Enter' && !option.disabled && onToggle(option.value)}\n              className={cn('flex-1 cursor-pointer text-left', isSelected && 'font-medium')}\n            >\n              {option.label}\n            </button>\n          </>\n        ) : (\n          <button\n            type=\"button\"\n            disabled={option.disabled}\n            onClick={() => !option.disabled && onToggle(option.value)}\n            className={cn(\n              'flex flex-1 cursor-pointer items-center justify-between rounded-sm px-1 py-0.5 text-left hover:bg-accent/50',\n              isSelected && 'font-medium',\n            )}\n          >\n            <span>{option.label}</span>\n            {isSelected && <Check className=\"size-3.5 text-primary\" />}\n          </button>\n        )}\n      </div>\n      {expanded && option.children && (\n        <ul className=\"pl-4\">\n          {option.children.map((child) => (\n            <TreeNode\n              key={child.value}\n              option={child}\n              selected={selected}\n              onToggle={onToggle}\n              multiple={multiple}\n            />\n          ))}\n        </ul>\n      )}\n    </li>\n  )\n}\n\nexport function TreeSelect({\n  value = [],\n  onChange,\n  options = [],\n  placeholder = 'Select...',\n  disabled,\n  required,\n  allowClear,\n  multiple = false,\n  className,\n}: TreeSelectProps) {\n  const [open, setOpen] = React.useState(false)\n  const label = value.length ? getLabels(options, value) : null\n  const showClear = allowClear && label && !disabled && !required\n\n  function handleClear(\n    event: React.PointerEvent<HTMLButtonElement> | React.MouseEvent<HTMLButtonElement>,\n  ) {\n    event.preventDefault()\n    event.stopPropagation()\n    onChange?.([])\n    setOpen(false)\n  }\n\n  function toggle(val: string) {\n    if (multiple) {\n      const next = value.includes(val) ? value.filter((v) => v !== val) : [...value, val]\n      onChange?.(next)\n    } else {\n      onChange?.([val])\n      setOpen(false)\n    }\n  }\n\n  return (\n    <Popover open={open} onOpenChange={setOpen}>\n      <div className={cn('relative w-full', className)}>\n        <PopoverTrigger asChild>\n          <Button\n            variant=\"outline\"\n            disabled={disabled}\n            className={cn(\n              'w-full justify-start font-normal',\n              showClear && 'pr-8',\n              !label && 'text-muted-foreground',\n            )}\n          >\n            <span className=\"flex-1 truncate text-left\">{label ?? placeholder}</span>\n          </Button>\n        </PopoverTrigger>\n        {showClear && (\n          <button\n            type=\"button\"\n            tabIndex={-1}\n            aria-label=\"Clear selection\"\n            onPointerDown={handleClear}\n            onClick={handleClear}\n            className=\"absolute top-1/2 right-2 z-10 flex size-5 -translate-y-1/2 items-center justify-center text-muted-foreground transition-colors hover:text-foreground\"\n          >\n            <X size={14} />\n          </button>\n        )}\n      </div>\n      <PopoverContent className=\"w-64 p-1\" align=\"start\">\n        <ul className=\"max-h-56 overflow-y-auto\">\n          {options.map((opt) => (\n            <TreeNode\n              key={opt.value}\n              option={opt}\n              selected={value}\n              onToggle={toggle}\n              multiple={multiple}\n            />\n          ))}\n        </ul>\n      </PopoverContent>\n    </Popover>\n  )\n}\n",
