            "target": "pro-fields/upload.tsx",
            "content": "'use client'\n\nimport { File, Upload as UploadIcon, X } from 'lucide-react'\nimport * as React from 'react'\nimport { cn } from '@/lib/utils'\n\nexport interface UploadFile {\n  uid: string\n  name: string\n  url?: string\n  status?: 'uploading' | 'done' | 'error'\n  size?: number\n}\n\nexport interface UploadProps {\n  value?: UploadFile[]\n  onChange?: (files: UploadFile[]) => void\n  accept?: string\n  multiple?: boolean\n  maxCount?: number\n  disabled?: boolean\n  placeholder?: string\n  className?: string\n}\n\nexport function Upload({\n  value = [],\n  onChange,\n  accept,\n  multiple = true,\n  maxCount,\n  disabled,\n  placeholder = 'Click or drag to upload',\n  className,\n}: UploadProps) {\n  const inputRef = React.useRef<HTMLInputElement>(null)\n  const [dragging, setDragging] = React.useState(false)\n\n  function addFiles(files: FileList | null) {\n    if (!files) return\n    const newFiles: UploadFile[] = Array.from(files).map((f) => ({\n      uid: `${Date.now()}-${Math.random()}`,\n      name: f.name,\n      size: f.size,\n      status: 'done' as const,\n      url: URL.createObjectURL(f),\n    }))\n    const merged = multiple ? [...value, ...newFiles] : [newFiles[0]]\n    const sliced = maxCount ? merged.slice(0, maxCount) : merged\n    onChange?.(sliced)\n  }\n\n  function removeFile(uid: string) {\n    const removed = value.find((f) => f.uid === uid)\n    if (removed?.url?.startsWith('blob:')) URL.revokeObjectURL(removed.url)\n    onChange?.(value.filter((f) => f.uid !== uid))\n  }\n\n  const reachedMax = maxCount !== undefined && value.length >= maxCount\n\n  return (\n    <div className={cn('space-y-2', className)}>\n      {!reachedMax && (\n        <button\n          type=\"button\"\n          aria-label=\"Upload files\"\n          disabled={disabled}\n          className={cn(\n            'flex w-full flex-col items-center justify-center gap-2 rounded-md border-2 border-dashed p-6',\n            'text-sm text-muted-foreground transition-colors cursor-pointer',\n            dragging && 'border-primary bg-primary/5',\n            disabled && 'opacity-50 cursor-not-allowed',\n            !disabled && 'hover:border-primary hover:bg-primary/5',\n          )}\n          onClick={() => inputRef.current?.click()}\n          onDragOver={(e) => {\n            e.preventDefault()\n            !disabled && setDragging(true)\n          }}\n          onDragLeave={() => setDragging(false)}\n          onDrop={(e) => {\n            e.preventDefault()\n            setDragging(false)\n            if (!disabled) addFiles(e.dataTransfer.files)\n          }}\n        >\n          <UploadIcon className=\"size-6\" />\n          <span>{placeholder}</span>\n        </button>\n      )}\n      <input\n        ref={inputRef}\n        type=\"file\"\n        className=\"hidden\"\n        accept={accept}\n        multiple={multiple}\n        onChange={(e) => addFiles(e.target.files)}\n      />\n      {value.length > 0 && (\n        <ul className=\"space-y-1\">\n          {value.map((f) => (\n            <li\n              key={f.uid}\n              className=\"flex items-center gap-2 rounded-md border px-3 py-1.5 text-sm\"\n            >\n              <File className=\"size-4 shrink-0 text-muted-foreground\" />\n              <span className=\"flex-1 truncate\">{f.name}</span>\n              {!disabled && (\n                <button\n                  type=\"button\"\n                  aria-label={`Remove ${f.name}`}\n                  onClick={() => removeFile(f.uid)}\n                  className=\"text-muted-foreground hover:text-foreground\"\n                >\n                  <X className=\"size-3.5\" />\n                </button>\n              )}\n            </li>\n          ))}\n        </ul>\n      )}\n    </div>\n  )\n}\n",
